// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 ts1, uint256 ts2, uint256 blk1, uint256 blk2, address a1, address a2) public {
        vm.assume(ts2 > ts1);
        vm.assume(ts1 > 0);
        vm.assume(blk1 % 15 != 0);
        vm.assume(blk2 % 15 != 0);
        vm.assume(a1 != address(0));
        vm.assume(a2 != address(0));
        vm.assume(a1 != a2);
        vm.deal(a1, 10 ether);
        vm.warp(ts1);
        vm.roll(blk1);
        vm.prank(a1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");
        vm.deal(a2, 10 ether);
        vm.warp(ts2);
        vm.roll(blk2);
        vm.prank(a2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");
        assertEq(c.pastBlockTime(), ts2);
    }
}
